def set_commission(commission_ratio=0.0003, min_commission=5.0, type=AssetType.STOCK.value):
    if commission_ratio <= 0 or min_commission <= 0:
        raise IQInvalidArgument('佣金费率和最低交易佣金不能小于或者等于0,请核对后重新输入')
    engine = Engine.instance()
    if type.upper() not in (AssetType.STOCK.value, AssetType.ETF.value, AssetType.LOF.value):
        strategy_log.warning("设置类型入参有误，设置失败，请输入'STOCK/stock'、'ETF/etf'或'LOF/lof'")
        return None
    else:
        commission = engine.get_commission(type.upper())
        if commission:
            commission.set_commission(float(commission_ratio), float(min_commission))
            return None
