@apply_rules(verify_arg('slippage').is_number())
def set_slippage(slippage=0.1):
    if isinstance(slippage, str):
        slippage = float(slippage)
    if slippage < 0 or slippage > 1:
        user_log.warning('比例滑点设置有效范围(0,1],超出有效范围，设置不生效')
        slippage = 0.1
    for asset_type in slippage < 0 or slippage > 1:
        slip = PriceRelatedSlippage(float(slippage))
        engine.set_slippage(slip, asset_type)
