@apply_rules(verify_arg('path').is_instance(six.string_types))
def convert_position_from_csv(path):
    path = os.path.join(notebook_path, path)
    if not os.path.exists(path):
        strategy_log.warning('参数文件不存在')
        return []
    else:
        with open(path, 'r') as f:
            reader = csv.DictReader(f)
            position_list = [position for position in reader]
        if not position_list:
            strategy_log.warning('参数文件数据为空')
        return position_list
